  base jsonb; c jsonb; o jsonb; x jsonb; p text[]; hasil text[]; harapan text[]; n int := 0; d text; 
begin
  base := vek -> 'base';
  select pg_get_functiondef(pr.oid) into d from pg_proc pr where pr.proname = 'keu_kebijakan_periksa' and pr.pronamespace = 'public'::regnamespace;
  if position('honor_innas' in d) = 0 then raise exception 'GAGAL: pemeriksa belum ditambal (jalankan 20261029a)'; end if;
  if jsonb_array_length(base -> 'param') <> 24 then raise exception 'GAGAL: basis vektor harus 24 parameter'; end if;
  for c in select value from jsonb_array_elements(vek -> 'cases') loop
    x := base;
    for o in select value from jsonb_array_elements(c -> 'ops') loop
      p := array(select jsonb_array_elements_text(o -> 'path'));
      if o ->> 'op' = 'set' then x := jsonb_set(x, p, o -> 'value', true);
      elsif o ->> 'op' = 'del' then x := x #- p;
      elsif o ->> 'op' = 'tambah' then x := jsonb_set(x, p, (x #> p) || jsonb_build_array(o -> 'value'));
      elsif o ->> 'op' = 'ganti' then x := o -> 'value';
      end if;
    end loop;
    hasil := array(select e from unnest(keu_kebijakan_periksa(x)) e order by e);
    harapan := array(select jsonb_array_elements_text(c -> 'galat') order by 1);
    if hasil is distinct from harapan then raise exception 'GAGAL: kasus "%": SQL %, harapan %', c ->> 'nama', hasil, harapan; end if;
    n := n + 1;
  end loop;
  if n <> 45 then raise exception 'GAGAL: seharusnya 45 kasus, dijalankan %', n; end if;
  -- lembar lama (21 parameter wajib, tanpa parameter opsional) dan lembar tanpa parameter honor tetap sah; parameter wajib lain tetap diperiksa
  x := jsonb_set(base, '{param}', (base -> 'param') - 23 - 22);
  if cardinality(keu_kebijakan_periksa(x)) <> 0 then raise exception 'GAGAL: lembar tanpa parameter honor harus sah'; end if;
  x := jsonb_set(base, '{param}', (base -> 'param') - 23 - 22 - 21);
  if cardinality(keu_kebijakan_periksa(x)) <> 0 then raise exception 'GAGAL: lembar 21 parameter harus sah'; end if;
  x := jsonb_set(x, '{param}', (x -> 'param') - 20);
  if keu_kebijakan_periksa(x) <> array['Parameter batas_spj belum ada'] then raise exception 'GAGAL: parameter wajib tetap diperiksa'; end if;
  raise notice 'LULUS 76 (% kasus)', n;
end $$;
rollback;
